[
  {
    "kind": "narration",
    "text": "Wren waits patiently, her eyes scanning the horizon.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "action",
    "text": "Ash attempts to communicate with Wren, trying to convey the plan for their dawn patrol.",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "dialogue",
    "speaker_id": "b9c92e8b-dcba-4dfe-9db0-db8af069ac8a",
    "text": "\"The mill road is clear.\" Wren assures Ash, her voice steady.",
    "cited_fact_keys": ["reaction:9fc8efec-427e-5d30-8ab2-d64c5ae784fe"]
  }
]

[
  {
    "kind": "narration",
    "text": "Ash tries to discuss the dawn patrol with Wren, but Wren remains silent, waiting.",
    "cited_fact_keys": ["attempt:communicate", "attempt:wait"],
    "speaker_id": null
  },
  {
    "kind": "dialogue",
    "text": "Wren finally breaks the silence, 'Ash, we need to talk about the lamps.'",
    "cited_fact_keys": ["reaction:29db82ba-342d-525e-9d64-5a14663378e9"],
    "speaker_id": "ae67350f-35cb-4eea-b1f7-ba7ec103095a"
  }
]

[
  {
    "kind": "narration",
    "speaker_id": null,
    "cited_fact_keys": [
      "attempt:communicate"
    ],
    "text": "Ash tries to communicate with Wren about the dawn patrol."
  },
  {
    "kind": "narration",
    "speaker_id": null,
    "cited_fact_keys": [
      "attempt:wait"
    ],
    "text": "Meanwhile, Wren waits patiently."
  },
  {
    "kind": "narration",
    "speaker_id": null,
    "cited_fact_keys": [
      "reaction:29db82ba-342d-525e-9d64-5a14663378e9"
    ],
    "text": "Wren discusses the lamps with Ash."
  }
]

[
  {
    "kind": "narration",
    "text": "Ash waits patiently.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "narration",
    "text": "Meanwhile, Wren tries to get Ash's attention, asking, 'Where is the mill?'",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "dialogue",
    "text": "'Past the bridge, second left.'",
    "cited_fact_keys": ["reaction:8520c36d-e398-5f40-87fe-6cd8491e2d33"],
    "speaker_id": "c5d5cc97-bed3-4745-8ac4-a00f613620f4"
  }
]

[
  {
    "kind": "narration",
    "text": "Ash stood patiently, waiting.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "action",
    "text": "Meanwhile, Wren tried to engage Ash in conversation.",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "dialogue",
    "text": "\"Grain and oilskins.\" Ash responded curtly.",
    "cited_fact_keys": ["reaction:a2f4a15c-4079-548d-a237-6c2e1db1e75f"],
    "speaker_id": "55cd77b3-d251-4c7f-9ac4-2109aa2a232c"
  }
]

[
  {
    "kind": "narration",
    "text": "Wren attempts to communicate with Ash, asking, 'Who keeps the lighthouse at night?'",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "action",
    "text": "Ash waits for Wren's question.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "dialogue",
    "text": "'Old Marlow, if the lamp is still lit.'",
    "cited_fact_keys": ["reaction:42a093ea-807b-5490-b590-bb5498a247b9"],
    "speaker_id": "e41291e5-ac69-4bc5-97b3-64a83fda1feb"
  }
]

[
  {
    "kind": "narration",
    "text": "Wren tries to catch Ash's attention, eager to know if the stalls are open yet.",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "narration",
    "text": "Ash, patiently waiting, hears Wren's query.",
    "cited_fact_keys": ["attempt:wait", "attempt:communicate"]
  },
  {
    "kind": "dialogue",
    "text": "\"Stalls open at second bell.\" Ash informs Wren.",
    "cited_fact_keys": ["reaction:1a9de298-959e-556e-aa27-e12fee6bc996"],
    "speaker_id": "db3bf895-978c-4263-9c26-4594f5203265"
  }
]

[
  {
    "kind": "narration",
    "text": "Wren tries to initiate a conversation with Ash, the topic at hand being their dawn patrol.",
    "cited_fact_keys": ["attempt:communicate"],
    "speaker_id": null
  },
  {
    "kind": "action",
    "text": "Meanwhile, Ash patiently waits.",
    "cited_fact_keys": ["attempt:wait"],
    "speaker_id": null
  }
]

[
  {
    "kind": "narration",
    "text": "Wren attempts to communicate with Ash about the dawn patrol, but Ash is preoccupied.",
    "cited_fact_keys": ["attempt:communicate"],
    "speaker_id": null
  },
  {
    "kind": "narration",
    "text": "Meanwhile, Marlow tries to convey a message to Wren about the road's condition.",
    "cited_fact_keys": ["attempt:communicate"],
    "speaker_id": null
  },
  {
    "kind": "narration",
    "text": "Ash, lost in thought, waits for the others to finish their conversations.",
    "cited_fact_keys": ["attempt:wait"],
    "speaker_id": null
  },
  {
    "kind": "dialogue",
    "text": "Ash turns to Wren, 'Dawn bell means the first stalls are opening.'",
    "cited_fact_keys": ["reaction:227e9d2f-4dec-57cd-885a-b056cbadcf3c"],
    "speaker_id": "65e37b74-d528-49fa-b1b7-bf5bfc77744f"
  },
  {
    "kind": "dialogue",
    "text": "Marlow adds, 'Aye, and mind the loose stones past the bridge.'",
    "cited_fact_keys": ["reaction:75d92072-c90d-50b7-acf7-74885289832d"],
    "speaker_id": "63d8b2de-a4aa-4c77-a0b3-3301804f8ec8"
  }
]

[
  {
    "kind": "narration",
    "text": "Wren attempts to communicate with Ash about the dawn patrol.",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "narration",
    "text": "Marlow observes the scene unfolding.",
    "cited_fact_keys": ["attempt:observe"]
  },
  {
    "kind": "narration",
    "text": "Ash patiently waits for Wren to speak.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "dialogue",
    "text": "\"Dawn bell means the market's waking.\"",
    "speaker_id": "33e37458-383a-468a-9eff-5d9612657689",
    "cited_fact_keys": ["reaction:4e3981e1-d0e0-50ba-aa04-cc9c18fc435b"]
  }
]

[
  {
    "kind": "narration",
    "text": "Wren attempts to communicate with Ash, trying to discuss their plans for the journey ahead.",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "narration",
    "text": "Ash, meanwhile, waits patiently for Wren to finish.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "dialogue",
    "text": "\"Dawn bell means the market is waking early today, so hurry down with coin and basket before the best bread and freshest fish are gone from the stalls.\"",
    "cited_fact_keys": ["reaction:545ec852-ca9c-5e4d-a178-130d8f0520fc"],
    "speaker_id": "cfe877aa-1969-41f4-845d-3443712ef831"
  }
]

[
  {
    "kind": "narration",
    "text": "Ash waits patiently, his gaze fixed on the old bridge.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "action",
    "text": "Meanwhile, Wren attempts to engage Ash in conversation.",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "dialogue",
    "speaker_id": "43e13ab2-64c5-4dcc-8f87-5f6071fd5933",
    "text": "\"No.\" Ash responds curtly to Wren's question about the bridge's safety.",
    "cited_fact_keys": ["reaction:1c9a75e5-11b3-5758-8df1-42cc7eb28a94"]
  }
]

[
  {
    "kind": "narration",
    "text": "Wren attempts to communicate with Ash, asking about the mill.",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "action",
    "text": "Ash waits for Wren's response.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "dialogue",
    "speaker_id": "cd8ee8a3-3245-4a88-a438-7d4600f3feeb",
    "text": "It's still standing, unless someone's moved it.",
    "cited_fact_keys": ["reaction:2d7e6109-bbdc-582a-9967-81982647cb11"]
  }
]
